func (f *Forwarder) newClusterSessionRemoteCluster(ctx authContext) (*clusterSession, error) {
	sess := &clusterSession{
		parent:      f,
		authContext: ctx,
	}
	var err error
	sess.tlsConfig, err = f.getOrRequestCredentials(ctx)
	if err != nil {
		f.log.Warningf("Failed to get certificate for %v: %v.", ctx, err)
		return nil, trace.AccessDenied("access denied: failed to authenticate with auth server")
	}
	// remote clusters use special hardcoded URL,
	// and use a special dialer
	sess.authContext.teleportCluster.targetAddr = reversetunnel.LocalKubernetes
	transport := f.newTransport(sess.Dial, sess.tlsConfig)

	sess.forwarder, err = forward.New(
		forward.FlushInterval(100*time.Millisecond),
		forward.RoundTripper(transport),
		forward.WebsocketDial(sess.Dial),
		forward.Logger(f.log),
	)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return sess, nil
}

func (f *Forwarder) newClusterSessionSameCluster(ctx authContext) (*clusterSession, error) {
	kubeServices, err := f.CachingAuthClient.GetKubeServices(f.ctx)
	if err != nil && !trace.IsNotFound(err) {
		return nil, trace.Wrap(err)
	}
	if len(kubeServices) == 0 && ctx.kubeCluster == ctx.teleportCluster.name {
		return f.newClusterSessionLocal(ctx)
	}
	// Validate that the requested kube cluster is registered.
	var endpoints []services.Server
outer:
	for _, s := range kubeServices {
		for _, k := range s.GetKubernetesClusters() {
			if k.Name != ctx.kubeCluster {
				continue
			}
			// TODO(awly): check RBAC
			endpoints = append(endpoints, s)
			continue outer
		}
	}
	if len(endpoints) == 0 {
		return nil, trace.NotFound("kubernetes cluster %q is not found in teleport cluster %q", ctx.kubeCluster, ctx.teleportCluster.name)
	}
	// Try to use local credentials first.
	if _, ok := f.creds[ctx.kubeCluster]; ok {
		return f.newClusterSessionLocal(ctx)
	}
	// Pick a random kubernetes_service to serve this request.
	//
	// Ideally, we should try a few of the endpoints at random until one
	// succeeds. But this is simpler for now.
	endpoint := endpoints[mathrand.Intn(len(endpoints))]
	return f.newClusterSessionDirect(ctx, endpoint)
}

func (f *Forwarder) newClusterSessionLocal(ctx authContext) (*clusterSession, error) {
	f.log.Debugf("Handling kubernetes session for %v using local credentials.", ctx)
	sess := &clusterSession{
		parent:      f,
		authContext: ctx,
	}
	if len(f.creds) == 0 {
		return nil, trace.NotFound("this Teleport process is not configured for direct Kubernetes access; you likely need to 'tsh login' into a leaf cluster or 'tsh kube login' into a different kubernetes cluster")
	}
	creds, ok := f.creds[ctx.kubeCluster]
	if !ok {
		return nil, trace.NotFound("kubernetes cluster %q not found", ctx.kubeCluster)
	}
	sess.creds = creds
	sess.authContext.teleportCluster.targetAddr = creds.targetAddr
	sess.tlsConfig = creds.tlsConfig

	// When running inside Kubernetes cluster or using auth/exec providers,
	// kubeconfig provides a transport wrapper that adds a bearer token to
	// requests
	//
	// When forwarding request to a remote cluster, this is not needed
	// as the proxy uses client cert auth to reach out to remote proxy.
	transport, err := creds.wrapTransport(f.newTransport(sess.Dial, sess.tlsConfig))
	if err != nil {
		return nil, trace.Wrap(err)
	}

	fwd, err := forward.New(
		forward.FlushInterval(100*time.Millisecond),
		forward.RoundTripper(transport),
		forward.WebsocketDial(sess.Dial),
		forward.Logger(f.log),
	)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	sess.forwarder = fwd
	return sess, nil
}

func (f *Forwarder) newClusterSessionDirect(ctx authContext, kubeService services.Server) (*clusterSession, error) {
	f.log.WithFields(log.Fields{
		"kubernetes_service.name": kubeService.GetName(),
		"kubernetes_service.addr": kubeService.GetAddr(),
	}).Debugf("Kubernetes session for %v forwarded to remote kubernetes_service instance.", ctx)
	sess := &clusterSession{
		parent:      f,
		authContext: ctx,
		// This session talks to a kubernetes_service, which should handle
		// audit logging. Avoid duplicate logging.
		noAuditEvents: true,
	}
	// Set both addr and serverID, in case this is a kubernetes_service
	// connected over a tunnel.
	sess.authContext.teleportCluster.targetAddr = kubeService.GetAddr()
	sess.authContext.teleportCluster.serverID = fmt.Sprintf("%s.%s", kubeService.GetName(), ctx.teleportCluster.name)

	var err error
	sess.tlsConfig, err = f.getOrRequestCredentials(ctx)
	if err != nil {
		f.log.Warningf("Failed to get certificate for %v: %v.", ctx, err)
		return nil, trace.AccessDenied("access denied: failed to authenticate with auth server")
	}

	transport := f.newTransport(sess.Dial, sess.tlsConfig)

	sess.forwarder, err = forward.New(
		forward.FlushInterval(100*time.Millisecond),
		forward.RoundTripper(transport),
		forward.WebsocketDial(sess.Dial),
		forward.Logger(f.log),
	)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return sess, nil
}

// DialFunc is a network dialer function that returns a network connection
type DialFunc func(string, string) (net.Conn, error)

func (f *Forwarder) newTransport(dial DialFunc, tlsConfig *tls.Config) *http.Transport {
	return &http.Transport{
		Dial:            dial,
		TLSClientConfig: tlsConfig,
		// Increase the size of the connection pool. This substantially improves the
		// performance of Teleport under load as it reduces the number of TLS
		// handshakes performed.
		MaxIdleConns:        defaults.HTTPMaxIdleConns,
		MaxIdleConnsPerHost: defaults.HTTPMaxIdleConnsPerHost,
		// IdleConnTimeout defines the maximum amount of time before idle connections
		// are closed. Leaving this unset will lead to connections open forever and
		// will cause memory leaks in a long running process.
		IdleConnTimeout: defaults.HTTPIdleTimeout,
	}
}

const minimumCredentialValidity = time.Minute

// getOrRequestCredentials returns credentials cached for this authenticated
// context, or makes one serialized CSR request and caches its result.
func (f *Forwarder) getOrRequestCredentials(ctx authContext) (*tls.Config, error) {
	key := ctx.key()
	for {
		if tlsConfig := f.getCachedCredentials(key); tlsConfig != nil {
			return tlsConfig, nil
		}

		f.mu.Lock()
		if f.credentialRequests == nil {
			f.credentialRequests = make(map[string]*credentialRequest)
		}
		if request := f.credentialRequests[key]; request != nil {
			f.mu.Unlock()
			select {
			case <-request.done:
				if request.err != nil {
					return nil, trace.Wrap(request.err)
				}
				if f.credentialsValid(request.tlsConfig) {
					return request.tlsConfig, nil
				}
				// The certificate may have crossed the validity threshold while
				// this request waited. Try again and serialize with any new CSR.
				continue
			case <-f.forwarderContext().Done():
				return nil, trace.BadParameter("forwarder is closing, aborting the request")
			}
		}
		request := &credentialRequest{done: make(chan struct{})}
		f.credentialRequests[key] = request
		f.mu.Unlock()

		tlsConfig, err := f.requestCertificate(ctx)
		if err == nil && !f.credentialsValid(tlsConfig) {
			err = trace.BadParameter("received Kubernetes credentials that expire in less than one minute")
		}
		if err == nil {
			f.cacheCredentials(key, ctx.sessionTTL, tlsConfig)
		}

		f.mu.Lock()
		request.tlsConfig = tlsConfig
		request.err = err
		delete(f.credentialRequests, key)
		close(request.done)
		f.mu.Unlock()
		return tlsConfig, trace.Wrap(err)
	}
}

func (f *Forwarder) forwarderContext() context.Context {
	if f.ctx == nil {
		return context.Background()
	}
	return f.ctx
}

func (f *Forwarder) credentialsValid(tlsConfig *tls.Config) bool {
	expires, err := credentialExpiry(tlsConfig)
	if err != nil {
		return false
	}
	now := time.Now()
	if f.Clock != nil {
		now = f.Clock.Now()
	}
	return !expires.Before(now.Add(minimumCredentialValidity))
}

func (f *Forwarder) getCachedCredentials(key string) *tls.Config {
	f.mu.Lock()
	defer f.mu.Unlock()
	if f.credentialCache == nil {
		return nil
	}
	value, ok := f.credentialCache.Get(key)
	if !ok {
		return nil
	}
	tlsConfig, ok := value.(*tls.Config)
	if !ok || !f.credentialsValid(tlsConfig) {
		f.credentialCache.Remove(key)
		return nil
	}
	return tlsConfig
}

func (f *Forwarder) cacheCredentials(key string, sessionTTL time.Duration, tlsConfig *tls.Config) {
	if f.credentialCache == nil {
		return
	}
	expires, err := credentialExpiry(tlsConfig)
	if err != nil {
		return
	}
	now := time.Now()
	if f.Clock != nil {
		now = f.Clock.Now()
	}
	ttl := expires.Sub(now)
	if sessionTTL > 0 && sessionTTL < ttl {
		ttl = sessionTTL
	}
	if ttl <= 0 {
		return
	}
	f.mu.Lock()
	defer f.mu.Unlock()
	if err := f.credentialCache.Set(key, tlsConfig, ttl); err != nil {
		f.log.WithError(err).Warn("Failed to cache Kubernetes credentials.")
	}
}

func credentialExpiry(tlsConfig *tls.Config) (time.Time, error) {
	if tlsConfig == nil || len(tlsConfig.Certificates) == 0 {
		return time.Time{}, trace.BadParameter("missing Kubernetes client certificate")
	}
	cert := tlsConfig.Certificates[0]
	if cert.Leaf != nil {
		return cert.Leaf.NotAfter, nil
	}
	if len(cert.Certificate) == 0 {
		return time.Time{}, trace.BadParameter("missing Kubernetes client certificate")
	}
	leaf, err := x509.ParseCertificate(cert.Certificate[0])
	if err != nil {
		return time.Time{}, trace.Wrap(err)
	}
	return leaf.NotAfter, nil
}

